// its own tiny module — like lib/dedicated-ip.ts's `dedicatedIpMonthlyCents` and
// lib/backup-upgrade.ts's `backupPlusMonthlyCents` — so a client component (the
// deploy wizard) never drags `lib/settings.ts` (and `db`) into the browser bundle:
// the wizard receives the resolved number as a prop instead.
import { getSettingInt } from "./settings";
import { DEFAULT_ANNUAL_DISCOUNT_PCT } from "./billing-terms";

/**
 * The annual (12-month) commitment discount actually charged, from the admin setting
 * (`annual_discount_percent`, default `DEFAULT_ANNUAL_DISCOUNT_PCT` = 10). The SINGLE
 * source of truth for the annual rate, so the deploy wizard's term card, the order
 * charge (lib/order.ts) and every renewal (renewalCharge) resolve the same number
 * and `displayed === charged === renewed` holds.
 *
 * NORMALISED to a whole percent in 0..90, exactly as `dedicatedIpMonthlyCents`
 * normalises its cents. `getSettingInt` is a raw `Number()` of whatever string sits
 * in the row, so it can return 12.5, -20 or 200; this value flows straight into
