   */
  taxRatePercent?: number;
};

export function renewalCharge(
  server: PricedServer,
  prices: RenewalPrices,
): RenewalCharge {
  const isGame = !!server.gamePlan;
  // The term to renew — the customer's chosen `Server.termMonths` (1 = monthly,
  // 12 = annual). A game term is now a per-order choice (Monthly / Annual) just like
  // a VPS, so it rides the Server row, not the plan.
  //
  // VPS/NxCloud terms are always one of the 4 standard `VPS_TERMS`, so we normalise
  // through `vpsTerm`. A GAME server, however, may historically carry ANY term the
  // plan was configured with (a pre-existing game server was created with
  // `termMonths = gamePlan.termMonths`, which the admin can set 1..36). We therefore
  // read the game term back RAW (clamped >= 1) rather than through `vpsTerm`, whose
  // fallback would collapse a non-standard legacy value (say 3) to monthly and
  // change that server's renewal cadence. For the seeded games (all `termMonths: 1`)
  // and any new Monthly/Annual order this is identical to the standard path.
  const months = isGame ? Math.max(1, Math.round(server.termMonths)) : vpsTerm(server.termMonths).months;
  // The annual discount to price the term at: the rate FROZEN on the server at sale,
  // falling back to the live setting for legacy/monthly rows. Both halves resolve
  // the same number, so an annual sub renews at the sold rate.
  const annualPct = server.annualDiscountPct ?? prices.annualDiscountPct;
  // Extra root disk is billed EVERY cycle at the current per-GB price. Game plans
  // are a flat all-in price and never carry the add-on lines.
  const extraDiskMonthlyCents = isGame ? 0 : extraDiskCentsAt(server.extraDiskGB, prices.extraDiskPerGbCents);
  const extraDiskCents = extraDiskMonthlyCents * months;
  // Paid backup retention (Plus) rides alongside extra disk: billed every cycle at
  // the current admin price, and — like every add-on line — NOT carried by a game
  // plan (renewalCharge's game branch is flat all-in, so game servers are never
  // sold a paid backup tier; see lib/backup-upgrade.ts's game guard).
  const backupMonthlyCents = isGame ? 0 : backupTierMonthlyCents(server.backupTier, prices.backupPlusCents);
  const backupCents = backupMonthlyCents * months;
  // A game plan's `priceCents` is its MONTHLY base (every seed is `termMonths: 1`).
  // Divide by the plan's own term so an admin plan configured as, say, a 3-month
  // bundle still yields a per-month rate; then price the customer's chosen term
  // through the SAME formula VPS uses. For a monthly game server this is exactly
  // `priceCents`; an ANNUAL game server renews at 12× that, less the annual discount.
  const gameMonthlyCents = isGame
    ? Math.round(server.gamePlan!.priceCents / Math.max(1, server.gamePlan!.termMonths))
    : 0;
  // LEGACY GUARD. Game servers sold BEFORE terms existed carry no frozen annual rate
  // (`annualDiscountPct == null`) and always renewed at the plan's FLAT `priceCents`,
  // with no term discount ever applied. Preserve that exactly so no pre-existing game
  // server's renewal moves — only servers sold through the new term-aware flow (which
  // always stamps a frozen `annualDiscountPct`) are priced with `termPriceCents`.
  //
  // GUARD ON isGame FIRST. This value is only USED in the isGame branch below, but a
  // bare ternary evaluates it for EVERY server — and a VPS `PricedServer` (e.g. the one
  // the deploy wizard builds, `gamePlan: null`, no `annualDiscountPct`) then hits the
  // `annualDiscountPct == null` arm and dereferences `server.gamePlan!.priceCents` on a
  // null, crashing the whole deploy page with "Cannot read properties of null". Compute
  // 0 for non-game so the null is never touched.
  const gameTotalCents = !isGame
    ? 0
    : server.annualDiscountPct == null
      ? server.gamePlan!.priceCents
      : termPriceCents(gameMonthlyCents, months, annualPct);
  const netCents = isGame
    ? gameTotalCents
    : vpsTermPriceCents(server.plan.priceCents, months, annualPct) +
      // Bill the IP surcharge only when the server ACTUALLY holds a dedicated IP,
      // not off the intent flag — a NAT-fallback server must never be charged for
      // an IP it never received.
      (server.dedicatedIp ? prices.ipMonthlyCents * months : 0) +
      extraDiskCents +
      backupCents;
  // VAT/GST on the pre-tax subtotal. Default rate 0 keeps `totalCents === netCents`
  // for every caller that does not pass the owner's rate (Finding 1).
  const taxRatePercent =
    Number.isFinite(prices.taxRatePercent) && (prices.taxRatePercent ?? 0) > 0 ? prices.taxRatePercent! : 0;

// Single fulfilment path for a paid Stripe Checkout session, shared by BOTH the
// success-redirect route and the webhook. Plain server module (not "use server").
//
// WHY THIS EXISTS (2026-07-25)
// Fulfilment used to live in `app/api/stripe/confirm/route.ts` and was gated on
// whether `creditCheckoutSession()` returned true. That boolean is true only for
// the caller that won the race to insert the wallet credit — and the webhook
// calls the same function and discards the result. So:
//
//   * Race: the webhook's insert lands first, the confirm request gets P2002,
//     `credited === false`, and the redirect quietly lands on an empty page.
//     $249 charged, $249 credited, no server, no error, no notification.
//   * Deterministic: the customer closes the tab before `success_url` resolves,
//     so the confirm route never runs at all. Same outcome, 100% reproducible.
//
// Stripe's own guidance is explicit that a browser redirect must not be the
// fulfilment trigger. Now BOTH callers run this, and a `FulfilledSession` row —
// its own marker, not a side effect of crediting — decides the single winner.

import { db } from "./db";
import { classifyCheckoutSession, creditCheckoutSession, retrieveCheckoutSession } from "./stripe";
import { placeOrder } from "./order";
import { placeGameOrder } from "./game-order";
import { applyResize } from "./resize";
import { applyDiskExpand } from "./disk-expand";

export type FulfilResult = {
  /** Where the browser should end up. The webhook ignores this. */
  redirect: string;
  /** True when THIS call performed the fulfilment work. */
  fulfilled: boolean;
  kind: "order" | "gameOrder" | "resize" | "diskExpand" | "topup" | "none";
  error?: string;
};

/**
 * Claim exclusive responsibility for fulfilling `sessionId`.
 * Returns false when another caller already holds the claim — the UNIQUE index,
 * not a read-then-write check, is what makes this safe under concurrency.
 */
async function claim(sessionId: string, kind: string): Promise<boolean> {
  try {
    await db.fulfilledSession.create({ data: { stripeSessionId: sessionId, kind } });
    return true;
  } catch (e) {
    if ((e as { code?: string })?.code === "P2002") return false; // someone else has it
    throw e;
  }
}

async function settle(sessionId: string, status: "DONE" | "FAILED", detail?: string) {
  await db.fulfilledSession
    .update({ where: { stripeSessionId: sessionId }, data: { status, detail: detail?.slice(0, 500) } })
    .catch(() => {});
}

/**
 * Tell the customer their money is safe and someone knows. Called only on a path
 * where the card HAS cleared and fulfilment did not happen, so silence is the one
 * outcome that is never acceptable.
 */
async function notifyStalled(userId: string) {
  await db.notification
    .create({
      data: {
        userId,
        title: "Payment received — we couldn't finish setting up your server",
        body: "Your payment is safe and sitting in your wallet. Our team has been alerted; deploy again or contact support and we'll sort it out.",
        href: "/dashboard/billing",
      },
    })
    .catch(() => {});
}

/**
 * Credit the wallet and fulfil whatever the session was for, exactly once.
 * Safe to call repeatedly and concurrently from the redirect and the webhook.
 *
 * THROWS when Stripe cannot be read. That is deliberate and it is the fix for the
 * defect found on 2026-07-27: this function used to ask three helpers for the
 * session, each of which swallowed every error into `null`, so a transient Stripe
 * failure was indistinguishable from "no purchase metadata" and fell through to
 * the top-up branch below reporting `fulfilled: true`. A real order then had its
 * card charged with no server, no FulfilledSession row and no notification — and
 * because the webhook returns 200 either way, Stripe never retried it. A throw
 * lands the browser on `?pending=1` (see app/api/stripe/confirm) and puts the
 * failure in the webhook's log, which is loud; declaring it a top-up was silent.
 */
export async function fulfilCheckoutSession(sessionId: string, base = ""): Promise<FulfilResult> {
  // ONE retrieve, one view of the session, shared by the credit and the routing.
  const session = await retrieveCheckoutSession(sessionId);
  const purpose = classifyCheckoutSession(session);

  // Nothing was paid (an abandoned session id, or one replayed before capture).
  // Never claim fulfilment for money that has not arrived.
  if (purpose.kind === "unpaid") {
    return { redirect: `${base}/dashboard/billing`, fulfilled: false, kind: "none" };
  }

  // Crediting is separately idempotent (UNIQUE stripeSessionId on the wallet
  // transaction). We deliberately IGNORE its return value now — it reports who
  // won the credit race, which is not the same question as "has this been
  // fulfilled", and conflating the two was the bug. A THROW, however, is not a
  // race: the money has not reached the wallet, so nothing below may spend it.
  await creditCheckoutSession(session);

  // Purchase metadata is present but cannot be trusted. Retrying will never fix
  // it, so claim the session and record the failure exactly like a failed order:
  // reconcilable, and the customer is told. What it must NEVER become is a silent
  // wallet top-up, which is precisely what the old `null` fall-through produced.
  if (purpose.kind === "unreadable") {
    if (await claim(sessionId, "unreadable")) {
      await settle(sessionId, "FAILED", purpose.detail);
      if (purpose.userId) await notifyStalled(purpose.userId);
    }
    return {
      redirect: `${base}/dashboard/billing?paid=1`,
      fulfilled: false,
      kind: "none",
      error: purpose.detail,
    };
  }

  const order = purpose.kind === "order" ? purpose : null;
  if (order) {
    if (!(await claim(sessionId, "order"))) {
      return { redirect: `${base}/dashboard/servers`, fulfilled: false, kind: "order" };
    }
    try {
      const user = await db.user.findUnique({ where: { id: order.userId } });
      if (!user) throw new Error("user not found for paid order");
      // Settle the price stamped on the session BEFORE the card was charged — never
      // a fresh quote taken now. The customer has already paid the card leg of that
      // exact total; re-pricing here and taking the difference out of the wallet is
      // the H2 incident (see OrderPrice in lib/order.ts). This is the same shape as
      // the resize and disk-expand branches below, which have always passed the
      // amount through metadata for this reason.
      // No request-scoped IP on the fulfil path (this can run in the webhook), so the
      // per-IP cap can't be enforced here — the per-account unique still holds, and
      // the first-month-free HOLD was already reserved (per-account AND per-IP) before
      // the card was charged, so the double-claim race is closed regardless. Fulfilment
      // CONFIRMS that hold via `promoReservationToken` rather than contending for a
      // fresh claim. `campaign` rides in via metadata so attribution survives the card
      // round-trip even in the webhook (no cookies).
      const serverId = await placeOrder(user, order.intent, order.sold, {
        ipHash: null,
        campaign: order.campaign,
        promoReservationToken: order.promoReservationToken,
        // Same discipline as the promo hold: the coupon was RESERVED (per-person + global
        // cap) before the card was charged, and placeOrder CONFIRMS that hold via this
        // token rather than contending for a fresh claim — no double-claim, no over-charge.
        couponReservationToken: order.couponReservationToken,
      });
      await settle(sessionId, "DONE", serverId);
      return { redirect: `${base}/dashboard/servers/${serverId}`, fulfilled: true, kind: "order" };
    } catch (e) {
      // Payment is captured and the funds are in the wallet — record the failure
      // so it is reconcilable rather than invisible, and tell the customer.
      const msg = String((e as Error)?.message ?? e);
      await settle(sessionId, "FAILED", msg);
      await notifyStalled(order.userId);
      return { redirect: `${base}/dashboard/deploy?paid=1`, fulfilled: false, kind: "order", error: msg };
    }
  }

  // Game-server order — the game analogue of the `order` branch above. Same claim /
  // settle / notify discipline; the card leg was credited to the wallet by
  // `creditCheckoutSession` above, then `placeGameOrder` debits the SOLD total back
  // out — never a fresh quote taken now (the H2 re-pricing incident). Game carries
  // no promo/coupon hold, so there is nothing to confirm and no per-IP concern here.
  const gameOrder = purpose.kind === "gameOrder" ? purpose : null;
  if (gameOrder) {
    if (!(await claim(sessionId, "gameOrder"))) {
      return { redirect: `${base}/dashboard/servers`, fulfilled: false, kind: "gameOrder" };
    }
    try {
      const user = await db.user.findUnique({ where: { id: gameOrder.userId } });
      if (!user) throw new Error("user not found for paid game order");
      const serverId = await placeGameOrder(user, gameOrder.intent, gameOrder.sold);
      await settle(sessionId, "DONE", serverId);
      return { redirect: `${base}/dashboard/servers/${serverId}`, fulfilled: true, kind: "gameOrder" };
    } catch (e) {
      // Payment is captured and the funds are in the wallet — record the failure so
      // it is reconcilable rather than invisible, and tell the customer.
      const msg = String((e as Error)?.message ?? e);
      await settle(sessionId, "FAILED", msg);
      await notifyStalled(gameOrder.userId);
      return { redirect: `${base}/dashboard/games?paid=1`, fulfilled: false, kind: "gameOrder", error: msg };
    }
  }

  const resize = purpose.kind === "resize" ? purpose : null;
  if (resize) {
    const back = `${base}/dashboard/servers/${resize.serverId}`;
    if (!(await claim(sessionId, "resize"))) {
      return { redirect: back, fulfilled: false, kind: "resize" };
    }
    try {
      await applyResize({
        serverId: resize.serverId,

      /** The first-month-free hold to confirm at fulfilment; null for a full-price order. */
      promoReservationToken: string | null;
      /** The checkout-coupon hold to confirm at fulfilment; null for a full-price order. */
      couponReservationToken: string | null;
    }
  | {
      kind: "gameOrder";
      userId: string;
      intent: GameOrderIntent;
      /** The price the game order was SOLD at; null only on a malformed stamp. */
      sold: GameOrderPrice | null;
    }
  | { kind: "resize"; userId: string; serverId: string; planId: string; chargeCents: number }
  | { kind: "diskExpand"; userId: string; serverId: string; addGB: number; chargeCents: number }
  /** No purchase metadata: a wallet top-up the customer bought for its own sake. */
  | { kind: "topup"; userId: string | null }
  /** Not paid (or paid to nobody) — nothing to fulfil and nothing to claim. */
  | { kind: "unpaid" }
  /** Purchase metadata IS present but cannot be trusted. Never treat as a top-up. */
  | { kind: "unreadable"; userId: string | null; detail: string };

/**
 * Classify a retrieved session. Pure — no clock, no network, no database — so the
 * routing decision is unit-testable and identical for the redirect and the webhook.
 */
export function classifyCheckoutSession(
  session: Pick<Stripe.Checkout.Session, "metadata" | "payment_status">,
): CheckoutPurpose {
  const md = session.metadata ?? null;
  const userId = parseId(md?.nxeonUserId);
  if (!userId || session.payment_status !== "paid") return { kind: "unpaid" };

  const orderRaw = md?.nxeonOrder;
  if (orderRaw) {
    let intent: unknown;
    try {
      intent = JSON.parse(orderRaw);
    } catch {
      return { kind: "unreadable", userId, detail: "nxeonOrder is not valid JSON" };
    }
    if (!intent || typeof intent !== "object") {
      return { kind: "unreadable", userId, detail: "nxeonOrder is not an object" };
    }
    return {
      kind: "order",
      userId,
      intent: intent as OrderIntent,
      sold: parseOrderPrice(session.metadata?.nxeonOrderPrice),
      campaign: sanitizeCampaign(md?.nxeonPromoCampaign),
      promoReservationToken: parseId(md?.nxeonPromoReservation),
      couponReservationToken: parseId(md?.nxeonCouponReservation),
    };
  }

  const gameRaw = md?.nxeonGameOrder;
  if (gameRaw) {
    let slim: Record<string, unknown>;
    try {
      slim = JSON.parse(gameRaw) as Record<string, unknown>;
    } catch {
      return { kind: "unreadable", userId, detail: "nxeonGameOrder is not valid JSON" };
    }
    if (!slim || typeof slim !== "object") {
      return { kind: "unreadable", userId, detail: "nxeonGameOrder is not an object" };
    }
    const gamePlanId = parseId(slim.gamePlanId);
    if (!gamePlanId) {
      return { kind: "unreadable", userId, detail: "nxeonGameOrder is missing gamePlanId" };
    }
    // The gameplay config rides in its own optional key; a missing/garbled blob is
    // simply dropped (placeGameOrder fills defaults), never treated as unreadable —
    // it is not money and cannot change the settled charge.
    let config: Record<string, unknown> | null = null;
    const rawCfg = md?.nxeonGameConfig;
    if (typeof rawCfg === "string" && rawCfg !== "") {
      try {
        const p = JSON.parse(rawCfg);
        if (p && typeof p === "object") config = p as Record<string, unknown>;
      } catch {
        config = null;
      }
    }
    const intent: GameOrderIntent = {
      gamePlanId,
      termMonths: typeof slim.termMonths === "number" ? slim.termMonths : 1,
      serverName: typeof slim.serverName === "string" ? slim.serverName : undefined,
      hostname: typeof slim.hostname === "string" ? slim.hostname : undefined,
      variant: typeof slim.variant === "string" ? slim.variant : undefined,
      config,
    };
    return { kind: "gameOrder", userId, intent, sold: parseGameOrderPrice(md?.nxeonGameOrderPrice) };
  }

  const resizeRaw = md?.nxeonResize;
  if (resizeRaw) {
    let p: Record<string, unknown>;
    try {
      p = JSON.parse(resizeRaw) as Record<string, unknown>;
    } catch {
      return { kind: "unreadable", userId, detail: "nxeonResize is not valid JSON" };
    }
    const serverId = parseId(p?.serverId);
    const planId = parseId(p?.planId);
    const chargeCents = parseChargeCents(p?.chargeCents);
    if (!serverId || !planId || chargeCents === null) {
      return { kind: "unreadable", userId, detail: "nxeonResize is missing serverId/planId/chargeCents" };
    }
    return { kind: "resize", userId, serverId, planId, chargeCents };
  }

